import Foundation

/// One numeric contract for all RX/TX surfaces, independent of utilization fields.
public struct NetworkPresentation {
 public let number: String
 public let unit: String
 public let available: Bool
  private let rawValue: Double?
 public var displayNumber: String { available ? MetricPresentation.number(rawValue.map { $0 / (unit == "MiB" ? 1_048_576 : 1024) }) : "Н/Д" }
 public var text: String { displayNumber + " " + unit + "/с" }
 public var compact: String { (available ? number : "000.0") + (unit == "MiB" ? "M" : "K") }
 public init(_ value: Double?) {
  rawValue = value
  available = value.map { $0.isFinite && $0 >= 0 } ?? false
  let kib = available ? value! / 1024 : 0
  // Round before comparing: 999.95 KiB must not render a seventh digit.
  let useMiB = (kib * 10).rounded() >= 10_000
  unit = useMiB ? "MiB" : "KiB"
  let scaled = useMiB ? kib / 1024 : kib
  guard available else { number = "  Н/Д"; return }
  guard scaled < 999.95 else { number = "+++.+"; return }
  let result = String(format: "%.1f", locale: Locale(identifier: "en_US_POSIX"), scaled)
  number = result.count <= 5 ? String(repeating: "0", count: 5 - result.count) + result : "+++.+"
 }
}

import Foundation

/// Measurement-only formatting. Counts, dates, addresses and exact byte evidence stay intact.
public enum MetricPresentation {
 public static let swapExplanation = "Использовано / выделено сейчас. Процент от текущего выделенного объёма SWAP, который может меняться; это не фиксированная ёмкость и не оценка состояния памяти. При нулевом объёме процент не определён. GiB = 2³⁰ байт."
 public static func number(_ value: Double?) -> String {
  guard let value, value.isFinite, value >= 0 else { return "Н/Д" }
  let text = String(format: "%.1f", locale: Locale(identifier: "en_US_POSIX"), value)
  return text
 }
 public static func battery(_ value: Double?) -> String {
  guard let value, value.isFinite, value >= 0, value <= 100 else { return "Н/Д" }
  return String(format: "%.0f%%", locale: Locale(identifier: "en_US_POSIX"), value)
 }
 public static func powerState(_ value: String) -> String {
  String(value.split(separator: "·", maxSplits: 1).first ?? "").trimmingCharacters(in: .whitespaces)
 }
 public static func percent(_ value: Double?) -> String {
  let text = number(value)
  return text == "Н/Д" ? text : text + " %"
 }
 public static func utilization(_ used: Int64?, total: Int64?) -> String {
  guard let used, let total, used >= 0, total > 0, used <= total else { return "Н/Д" }
  return percent(Double(used) / Double(total) * 100)
 }
 public static func size(_ value: Int64?) -> String {
  number(value.map { Double($0) / 1_073_741_824 }) + " GiB"
 }
 public static func usedTotal(_ used: Int64?, total: Int64?) -> String {
  number(used.map { Double($0) / 1_073_741_824 }) + " из " + size(total)
 }
 public static func capacity(_ used: Int64?, total: Int64?) -> String {
  utilization(used, total: total) + " · " + usedTotal(used, total: total)
 }
 /// Percentage of an explicit drawing scale, never of unknown link capacity.
 public static func scalePercent(_ rate: Double?) -> String {
  percent(rate.map { $0 / (10 * 1_048_576) * 100 }) + " шкалы 10.0 MiB/с"
 }
}

import AppKit

/// Shared with offscreen fixtures. Width changes only on explicit visibility changes.
enum StatusTypography {
 static let numericFont = NSFont.monospacedSystemFont(ofSize: 13, weight: .semibold)
 static let prefixFont = NSFont.systemFont(ofSize: 9, weight: .medium)
 static let arrowFont = NSFont.monospacedSystemFont(ofSize: 10, weight: .medium)
 static let templates = [
  ["000.0%", "000.0%", "000.0G", "000.0%", "↓000.0M", "↑000.0M"],
  ["+++.+%", "+++.+G", "+++.+G", "+++.+G", "↓+++.+M", "↑+++.+M"]
 ]
 static let fixedWidth = width(indices: Array(0..<6))
 static func width(indices: [Int]) -> CGFloat {
  guard !indices.isEmpty else { return 28 }
  return ceil(templates.map { template in title(indices.map { template[$0] }).size().width }.max()! + 16)
 }
 static func title(_ fields: [String], colors: [NSColor] = []) -> NSAttributedString {
  let result = NSMutableAttributedString(string: "")
  for (index, field) in fields.enumerated() {
   let color = colors.indices.contains(index) ? colors[index] : .labelColor
   if index > 0 { result.append(NSAttributedString(string: " ", attributes: [.font: numericFont])) }
   let arrow = field.hasPrefix("↓") || field.hasPrefix("↑")
   if arrow { result.append(NSAttributedString(string: String(field.prefix(1)), attributes: [.font: arrowFont, .foregroundColor: color])) }
   result.append(NSAttributedString(string: arrow ? String(field.dropFirst()) : field, attributes: [.font: numericFont, .foregroundColor: color]))
  }
  return result
 }
}
